package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.io.*;
public class FractionPlacementTest {
 @Test public void publicPointNotHiddenKey(){for(String raw:List.of("0/100","1/100","99/100","100/100","7/2","3 1/2","700/100")){Question q=FractionPlacement.make(raw);var g=FractionPlacement.read(q);assertNotNull(g);q.answers=new String[]{"poison"};q.expression="poison";String correct=g.tick()+"/"+g.denominator();assertTrue(new Checker().check(q,List.of(),List.of(correct)).correct());String wrong=(g.tick()==0?1:g.tick()-1)+"/"+g.denominator();assertFalse(new Checker().check(q,List.of(),List.of(wrong)).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("")).status);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
 @Test public void boundaryAndEquivalentCoordinates(){Question q=FractionPlacement.make("3 1/2");assertTrue(new Checker().check(q,List.of(),List.of("14/4")).correct());assertEquals(-1,FractionPlacement.selectedTick(q,"7/0"));assertEquals(-1,FractionPlacement.selectedTick(q,"29/4"));assertEquals(-1,FractionPlacement.selectedTick(q,"13/4"));q.diagram.values[2]=100;assertNull(FractionPlacement.read(q));for(String bad:List.of("8/1","701/100","1 2/101","-1/2"))try{FractionPlacement.make(bad);fail(bad);}catch(IllegalArgumentException expected){}}
 @Test public void ordinaryGradeSixAllFormsAndNoChoiceReplacement(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(FractionPlacement.ID,6));CurriculumLimits l=GlobalCurriculum.limits("na-nied-primary-2024-v1",FractionPlacement.ID,6);Generator generator=new Generator(new Random(277));List<String>recent=new ArrayList<>();boolean proper=false,improper=false,mixed=false,large=false;
  for(int i=0;i<100;i++){Question q=generator.next(FractionPlacement.ID,recent,true,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(q.choices.isEmpty());var g=FractionPlacement.read(q);assertNotNull(g);large|=g.denominator()>12;mixed|=g.raw().contains(" ");proper|=!g.raw().contains(" ")&&g.value().compareTo(Rational.of(1))<0;improper|=!g.raw().contains(" ")&&g.value().compareTo(Rational.of(1))>=0;assertTrue(l.allows(q));}
  assertTrue(proper&&improper&&mixed&&large);
 }
 @Test public void viewportAndChoiceSerializeIndependently()throws Exception{Learning.Session s=new Learning.Session();s.question=FractionPlacement.make("6 99/100");s.fractionPlacementQuestionId=s.question.id;s.fractionPlacementStartTick=690;s.answers.add("693/100");ByteArrayOutputStream out=new ByteArrayOutputStream();new ObjectOutputStream(out).writeObject(s);Learning.Session copy=(Learning.Session)new ObjectInputStream(new ByteArrayInputStream(out.toByteArray())).readObject();assertEquals(690,copy.fractionPlacementStartTick);assertEquals(s.question.id,copy.fractionPlacementQuestionId);assertEquals("693/100",copy.answers.get(0));assertEquals(693,FractionPlacement.selectedTick(copy.question,copy.answers.get(0)));assertFalse(new Checker().check(copy.question,List.of(),copy.answers).correct());}
}
